// AcceptMAXUpdate operation middleware
func (siw *ServerInterfaceWrapper) AcceptMAXUpdate(w http.ResponseWriter, r *http.Request) {

	var err error
	_ = err

	// Parameter object where we will unmarshal all parameters from the context
	var params AcceptMAXUpdateParams

	headers := r.Header

	// ------------- Optional header parameter "X-Demo-Campaign" -------------
	if valueList, found := headers[http.CanonicalHeaderKey("X-Demo-Campaign")]; found {
		var XDemoCampaign string
		n := len(valueList)
		if n != 1 {
			siw.ErrorHandlerFunc(w, r, &TooManyValuesForParamError{ParamName: "X-Demo-Campaign", Count: n})
			return
		}

		err = runtime.BindStyledParameterWithOptions("simple", "X-Demo-Campaign", valueList[0], &XDemoCampaign, runtime.BindStyledParameterOptions{ParamLocation: runtime.ParamLocationHeader, Explode: false, Required: false, Type: "string", Format: ""})
		if err != nil {
			siw.ErrorHandlerFunc(w, r, &InvalidParamFormatError{ParamName: "X-Demo-Campaign", Err: err})
			return
		}

		params.XDemoCampaign = XDemoCampaign

	}

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.AcceptMAXUpdate(w, r, params)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

